import * as THREE from 'three';
import { describe, expect, it } from 'vitest';
import type { Quat } from '../contracts/math';
import { RotatingBar } from './RotatingBar';
import { quaternionFromAxisAngle } from './rotation';
import type { ObstacleBodyHandle, ObstacleBodySpec, ObstaclePhysicsAdapter } from './types';

export class FakeBody implements ObstacleBodyHandle {
  readonly rotations: Quat[] = [];
  disposed = false;

  setNextRotation(rotation: Quat): void {
    this.rotations.push({ ...rotation });
  }

  dispose(): void {
    this.disposed = true;
  }
}

export class FakePhysics implements ObstaclePhysicsAdapter {
  readonly specs: ObstacleBodySpec[] = [];
  readonly bodies: FakeBody[] = [];

  createBody(spec: ObstacleBodySpec): ObstacleBodyHandle {
    this.specs.push(spec);
    const body = new FakeBody();
    this.bodies.push(body);
    return body;
  }
}

export function advance(obstacle: { update(deltaSeconds: number): void }, seconds: number): void {
  const delta = 1 / 60;
  const steps = Math.round(seconds / delta);
  for (let index = 0; index < steps; index += 1) obstacle.update(delta);
}

describe('RotatingBar configuration', () => {
  it('derives collider half extents from the visual size', () => {
    const bar = new RotatingBar({
      id: 'bar',
      position: { x: 1, y: 0, z: 2 },
      length: 5,
      thickness: 0.4,
      height: 0.5,
    });

    expect(bar.colliders).toHaveLength(1);
    expect(bar.colliders[0].halfExtents).toEqual({ x: 2.5, y: 0.25, z: 0.2 });
    expect(bar.colliders[0].offset).toEqual({ x: 0, y: 0, z: 0 });
    expect(bar.root.position.toArray()).toEqual([1, 0, 2]);
    expect(bar.axis).toEqual({ x: 0, y: 1, z: 0 });
  });

  it('rejects invalid configuration', () => {
    const position = { x: 0, y: 0, z: 0 };
    expect(() => new RotatingBar({ id: '  ', position })).toThrow(/non-empty id/);
    expect(() => new RotatingBar({ id: 'bar', position: { x: Number.NaN, y: 0, z: 0 } })).toThrow(/finite vector/);
    expect(() => new RotatingBar({ id: 'bar', position, length: -1 })).toThrow(/positive finite/);
    expect(() => new RotatingBar({ id: 'bar', position, thickness: 0 })).toThrow(/positive finite/);
  });
});

describe('RotatingBar movement', () => {
  it('rotates deterministically and mirrors the angle onto the pivot', () => {
    const bar = new RotatingBar({ id: 'bar', position: { x: 0, y: 0, z: 0 }, speed: Math.PI });

    advance(bar, 1);

    expect(bar.angle).toBeCloseTo(Math.PI, 6);
    expect(bar.pivot.quaternion.y).toBeCloseTo(1, 6);
    expect(bar.pivot.quaternion.w).toBeCloseTo(0, 6);
  });

  it('matches stepped playback with an explicit elapsed time', () => {
    const stepped = new RotatingBar({ id: 'a', position: { x: 0, y: 0, z: 0 }, speed: 2.5, phase: 0.4 });
    const jumped = new RotatingBar({ id: 'b', position: { x: 0, y: 0, z: 0 }, speed: 2.5, phase: 0.4 });

    advance(stepped, 2);
    jumped.setElapsed(2);

    expect(stepped.angle).toBeCloseTo(jumped.angle, 6);
  });

  it('stays still while disabled and resumes after being enabled', () => {
    const bar = new RotatingBar({ id: 'bar', position: { x: 0, y: 0, z: 0 }, speed: 3, enabled: false });

    advance(bar, 1);
    expect(bar.angle).toBe(0);

    bar.enabled = true;
    advance(bar, 1);
    expect(bar.angle).toBeCloseTo(3, 6);

    bar.reset();
    expect(bar.angle).toBe(0);
  });
});

describe('RotatingBar physics lifecycle', () => {
  it('creates a kinematic body and pushes every rotation update', () => {
    const physics = new FakePhysics();
    const bar = new RotatingBar({
      id: 'bar',
      position: { x: 2, y: 0.5, z: -1 },
      speed: 1,
      physics,
    });

    expect(physics.specs).toHaveLength(1);
    expect(physics.specs[0].kind).toBe('kinematic');
    expect(physics.specs[0].id).toBe('bar');
    expect(physics.specs[0].position).toEqual({ x: 2, y: 0.5, z: -1 });
    expect(physics.specs[0].colliders).toBe(bar.colliders);

    const body = physics.bodies[0];
    const before = body.rotations.length;
    advance(bar, 0.5);
    expect(body.rotations.length).toBe(before + 30);

    const expected = quaternionFromAxisAngle(bar.axis, bar.angle);
    const last = body.rotations[body.rotations.length - 1];
    expect(last.y).toBeCloseTo(expected.y, 6);
    expect(last.w).toBeCloseTo(expected.w, 6);
  });

  it('detaches from scene and physics on dispose', () => {
    const scene = new THREE.Scene();
    const physics = new FakePhysics();
    const bar = new RotatingBar({ id: 'bar', position: { x: 0, y: 0, z: 0 }, speed: 2, scene, physics });

